[[ ## document ## ]]
{
  "title": "PBC Request — Riverbend Dental Studio",
  "path": "engagements/riverbend-dental-studio/tax/2025-pbc-request.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "Prepared by Client Request — Riverbend Dental Studio"
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Tax Year Ending December 31, 2025"
      },
      {
        "kind": "paragraph",
        "text": "To the attention of: Riverbend Dental Studio — Owner/Office Manager"
      },
      {
        "kind": "paragraph",
        "text": "Thank you for engaging our firm for your 2025 tax return preparation. To complete the engagement efficiently, please provide the items listed below. Where an item is not applicable to your practice, please note “N/A” rather than leaving it blank. If you have questions, contact Colin Mackey (colin.mackey@firm.com)."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "1. General and Entity Information"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Copy of the entity's 2024 federal and state tax returns (if prior-year returns were prepared elsewhere).",
          "Any amendments, extensions, or IRS/state correspondence received during 2025.",
          "Entity formation documents, operating agreement, or amendments if changed during the year.",
          "List of owners (name, address, tax ID, ownership percentage, and any changes during 2025).",
          "Bank statements for all business accounts for the full year (January – December 2025)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "2. Income and Revenue Records"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Monthly or annual revenue summary by source (dental services, hygiene, product sales, lab fees reimbursed, etc.).",
          "1099-K, 1099-MISC, or merchant processor statements if applicable.",
          "Detailed accounts receivable aging report as of December 31, 2025.",
          "List of any bad debts written off during the year, with dates and amounts."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "3. Expenses and Cost of Goods Sold"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "General ledger or P&L detail for all expense accounts for 2025.",
          "Credit card statements (business and any personal cards used for business).",
          "Receipts or invoices for equipment purchases over $2,500, including financing documents.",
          "Vehicle log (mileage) if a vehicle is claimed for business use.",
          "Home office worksheet (square footage and allocation) if a home office deduction is claimed.",
          "Payroll summary and payroll tax filings (941s and state equivalents) for all quarters of 2025.",
          "Retirement plan contribution records (401k, SEP, SIMPLE) if applicable.",
          "Health insurance premiums paid for owners and employees.",
          "Rent or lease agreements for office space and equipment."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "4. Fixed Assets and Depreciation"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Fixed asset listing with dates placed in service, costs, and any disposals during 2025.",
          "Invoices for any new equipment, furniture, leasehold improvements, or vehicles purchased in 2025.",
          "Section 179 or bonus depreciation election worksheets if you intend to make these elections."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "5. Loans, Owner Transactions, and Other Items"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Loan statements (principal, interest paid, and ending balance) for any business loans.",
          "Schedule of owner draws, contributions, or loans to/from the business during 2025.",
          "Copy of any 1098 mortgage interest statements if the loan is secured by the business.",
          "Any 1099-NEC or 1099-MISC issued to contractors for services provided to the business.",
          "Estimated tax payment vouchers or proof of payments made during 2025.",
          "Sales tax filings and proof of remittance, if applicable in your state."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "6. Confirmations and Signatures"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Signed engagement letter (already provided; please return a signed copy if not yet done).",
          "Organizer questionnaire (attached separately).",
          "Representation letter to be signed at completion of the engagement."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Submission Instructions"
      },
      {
        "kind": "paragraph",
        "text": "Please upload documents to the secure client portal or email to Colin Mackey (colin.mackey@firm.com) in PDF or Excel format. For larger files, use the portal to avoid email size limits. Please submit all items by February 28, 2026, to allow timely filing of your return."
      },
      {
        "kind": "paragraph",
        "text": "Thank you for your cooperation."
      },
      {
        "kind": "paragraph",
        "text": "Colin Mackey\nStaff Accountant\nTax Department"
      }
    ]
  }
}
